const int clkPin = 2, dtPin = 3, swPin = 4;
int counter = 0, lastClk;
void setup() {
  pinMode(clkPin, INPUT); pinMode(dtPin, INPUT); pinMode(swPin, INPUT_PULLUP);
  lastClk = digitalRead(clkPin);
  Serial.begin(9600);
}
void loop() {
  int currentClk = digitalRead(clkPin);
  if (currentClk != lastClk && currentClk == 1) {
    if (digitalRead(dtPin) != currentClk) counter++; else counter--;
    Serial.print("Counter: "); Serial.println(counter);
  }
  lastClk = currentClk;
}
